import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import CommentPost from 'flarum/forum/components/CommentPost';
import PostControls from 'flarum/forum/utils/PostControls';
import Button from 'flarum/common/components/Button';
export { default as extend } from './extend';
function scanAndReportPostImages(component) {
  const mode = app.forum.attribute('huoxinAutoImageDimensionsMode') || 'client';
  if (mode === 'backend') return;

  // Only allow logged-in users with permission to report dimensions
  if (!app.session || !app.session.user) return;
  if (!app.forum.attribute('canReportImageDimensions')) return;
  const post = component.attrs.post;
  if (!post) return;
  const postId = post.id();
  if (!postId) return;
  const element = component.element;
  if (!element) return;

  // Find all images in this post, explicitly excluding emojis and 3rd party extension injections
  const images = element.querySelectorAll('.Post-body img:not(.emoji):not(.flamoji):not(.catchthefish-image):not([data-link-preview])');
  let batchedImages = [];
  let debounceTimer = null;
  const flushBatch = () => {
    if (batchedImages.length === 0) return;

    // Only take the first 100 images. Subsequent page views by this user or other users
    // will crowdsource the remaining images, because these first 100 will already be fixed!
    const payload = batchedImages.slice(0, 100);
    batchedImages = [];
    app.request({
      method: 'POST',
      url: app.forum.attribute('apiUrl') + '/auto-image-dimensions/report',
      body: {
        post_id: postId,
        images: payload
      }
    }).catch(e => {
      console.error('Failed to report image dimensions batch', e);
    });
  };
  images.forEach(img => {
    const hasFailedTag = img.hasAttribute('data-image-dimension-failed');
    const widthVal = img.getAttribute('width');
    const heightVal = img.getAttribute('height');
    const hasWidth = widthVal !== null && widthVal !== '';
    const hasHeight = heightVal !== null && heightVal !== '';
    if ((hasWidth || hasHeight) && !hasFailedTag) {
      return;
    }
    if (img.dataset.reported === 'true') {
      return;
    }
    const reportDimensions = () => {
      img.dataset.reported = 'true';
      const naturalWidth = img.naturalWidth;
      const naturalHeight = img.naturalHeight;
      if (naturalWidth > 0 && naturalHeight > 0) {
        batchedImages.push({
          url: img.src,
          width: naturalWidth,
          height: naturalHeight
        });

        // Debounce the flush
        if (debounceTimer) clearTimeout(debounceTimer);
        debounceTimer = window.setTimeout(flushBatch, 500);
      }
    };
    if (img.complete) {
      reportDimensions();
    } else {
      img.addEventListener('load', reportDimensions, {
        once: true
      });
    }
  });
}
app.initializers.add('huoxin-auto-image-dimensions', () => {
  extend(CommentPost.prototype, 'oncreate', function () {
    scanAndReportPostImages(this);
  });
  extend(CommentPost.prototype, 'onupdate', function () {
    scanAndReportPostImages(this);
  });
  extend(PostControls, 'moderationControls', function (items, post) {
    if (post.canRefreshImageDimensions()) {
      items.add('refreshImageDimensions', m(Button, {
        icon: "fas fa-sync",
        onclick: () => {
          app.request({
            method: 'POST',
            url: app.forum.attribute('apiUrl') + `/posts/${post.id()}/refresh-image-dimensions`
          }).then(() => {
            app.alerts.show({
              type: 'success'
            }, app.translator.trans('huoxin-auto-image-dimensions.forum.alerts.refresh_success'));
          });
        }
      }, app.translator.trans('huoxin-auto-image-dimensions.forum.post_controls.refresh_button')));
    }
  });
});